{"cards": [{"node_code": "N_b495248e3ba3c234", "definition": "研究射频接收链路前端低噪声放大器（LNA）的电路拓扑、噪声系数优化、增益带宽积及稳定性设计，涵盖从低频到毫米波频段的模拟电路实现。", "boundary": "聚焦于接收端信号放大环节，核心指标为噪声系数（NF）和增益。包括共源、共栅、交叉耦合等典型拓扑，偏置电路设计，输入输出阻抗匹配及稳定性分析。若内容主要涉及发射端功率放大或频率变换功能，则不在此列。", "includes": ["LNA电路拓扑设计与噪声系数优化", "射频输入输出阻抗匹配及稳定性分析", "LNA偏置电路及线性度/动态范围设计"], "excludes": ["射频功率放大器（PA）的功率效率与线性度设计", "混频器、频率合成器或锁相环（PLL）的频率变换电路"], "sibling_distinctions": [{"other_code": "N_8336cb95899487f0", "rule": "本节点侧重接收端信号放大与噪声控制；兄弟节点侧重发射端功率放大及信号频率变换。"}, {"other_code": "N_8645ed146ffd0f54", "rule": "本节点侧重单一功能模块（放大）的电路设计；兄弟节点侧重毫米波频段完整收发链路的系统级集成。"}], "cross_boundary_rule": "若电路主要功能为信号放大且关注噪声性能，归入本节点；若主要功能为功率输出或频率转换，归入射频功率放大器与混频器。"}, {"node_code": "N_8336cb95899487f0", "definition": "研究射频发射链路中功率放大器（PA）的效率、线性度及热管理，以及混频器（Mixer）的频率变换、本振泄漏抑制及无源/有源拓扑设计。", "boundary": "聚焦于发射端信号功率提升及信号频率搬移环节。PA部分关注功率附加效率（PAE）、三阶交调（IP3）及负载牵引；混频器部分关注变频损耗、隔离度及平衡结构。若内容主要涉及接收端低噪声放大，则不在此列。", "includes": ["射频功率放大器（PA）的线性度、效率及匹配网络设计", "有源/无源混频器拓扑、本振隔离及变频损耗优化", "射频频率变换电路及谐波抑制技术"], "excludes": ["接收端低噪声放大器（LNA）的噪声系数优化设计", "毫米波频段完整收发前端的系统级集成与封装"], "sibling_distinctions": [{"other_code": "N_b495248e3ba3c234", "rule": "本节点侧重发射端功率放大及频率变换；兄弟节点侧重接收端信号放大与噪声控制。"}, {"other_code": "N_8645ed146ffd0f54", "rule": "本节点侧重特定功能模块（PA/混频器）的电路设计；兄弟节点侧重毫米波频段完整收发链路的系统级集成。"}], "cross_boundary_rule": "若电路主要功能为功率输出或频率搬移，归入本节点；若主要功能为接收端低噪声放大，归入射频低噪声放大器。"}, {"node_code": "N_8645ed146ffd0f54", "definition": "研究毫米波频段（通常30GHz以上）收发前端集成电路的系统级设计，涵盖发射/接收链路集成、波束成形、天线接口及高频封装互连技术。", "boundary": "聚焦于毫米波频段的完整收发功能实现，强调高频下的寄生效应、片上互连及系统级性能。包括毫米波PA、LNA、混频器的集成，波束成形网络，以及天线与芯片的共封装（CoW）或片上天线（On-chip Antenna）设计。若仅涉及单一射频模块设计而无毫米波系统集成背景，则不在此列。", "includes": ["毫米波收发前端链路集成与波束成形电路设计", "毫米波频段片上互连、寄生效应补偿及高频封装技术", "毫米波天线接口电路及片上天线/共封装天线设计"], "excludes": ["低频段（如Sub-6GHz）射频收发电路设计", "单一射频模块（如仅LNA或仅PA）的独立电路拓扑设计"], "sibling_distinctions": [{"other_code": "N_b495248e3ba3c234", "rule": "本节点侧重毫米波频段完整收发链路的系统级集成；兄弟节点侧重单一功能模块（放大）的电路设计。"}, {"other_code": "N_8336cb95899487f0", "rule": "本节点侧重毫米波频段完整收发链路的系统级集成；兄弟节点侧重特定功能模块（PA/混频器）的电路设计。"}], "cross_boundary_rule": "若内容涉及毫米波频段完整收发链路集成、波束成形或高频封装互连，归入本节点；若仅涉及单一射频模块设计，归入相应的LNA或PA/混频器节点。"}]}
